 65	describe("reconcile-financial-statements executor (v6)", () => {
 66	  it("gold: the roll-forwards close, the four inventory presentations connect through the stated bridges, the two carrying amounts of dividends stay open inside a non-comparable account, and the two net debt definitions are not comparable", () => {
 67	    const result = reconcileFinancialStatements(camil());
 68	    expect(result.identities.map((identity) => [identity.id, identity.state])).toEqual([["balance_sheet", "holds"], ["debt_bridge", "holds"], ["cash_bridge", "holds"], ["interest_bridge", "not_comparable"]]);
 69	    expect(result.identities.find((identity) => identity.id === "interest_bridge")?.difference).toBe("1811");
 70	    // The income statement prints the expense in parentheses; the magnitude reading is declared and traced.
 71	    const interestTrace = result.trace.calculations.find((calculation) => calculation.id === "financial.interest_expense_bridge")!;
 72	    expect(interestTrace.operands.fromIncomeStatementPublished).toBe("-170548");
 73	    expect(interestTrace.operands.fromIncomeStatementRead).toBe("170548");
 74	    expect(interestTrace.operands.fromIncomeStatementSign).toBe("absolute");
 75	    const bridgeTrace = result.trace.calculations.find((calculation) => calculation.id === "financial.debt_balance_bridge")!;
 76	    expect(bridgeTrace.anchors.captacoes).toEqual(itr(40, "15, captações"));
 77	    expect(bridgeTrace.anchors.opening).toEqual(itr(40, "15, saldo em 28/02/2026"));
 78	    // Release figures enter with their published scale and a rounding half band of 50 thousand; the recomputed net debt closes within the tolerance, not "exactly".
 79	    expect(by(result, "net_debt_release").values.find((value) => value.source === "release")?.stated).toEqual({value: "4214.4", unit: "BRL million", decimals: 1, roundingHalfBand: "50"});
 80	    expect(by(result, "net_debt_release").rounding_half_band).toBe("50");
 81	    expect(by(result, "net_debt_release").closes_within).toBe("tolerance");
 82	    expect(result.trace.calculations.find((calculation) => calculation.id === "financial.accounting_identity:dividends:balanço (valor presente):derivation")?.operands["ajuste a valor presente"]).toBe("56435");
 83	    expect(Object.keys(result.identities.find((identity) => identity.id === "balance_sheet")!.anchors)).toEqual(["assets", "liabilities", "equity"]);
 84	    expect(result.identities.find((identity) => identity.id === "cash_bridge")?.anchors.netChange?.page).toBe(16);
 85	    expect(result.trace.calculations.find((calculation) => calculation.id === "financial.accounting_identity:net_debt_release:recalculado das notas:derivation")?.operands["dívida bruta"]).toBe("5670186");
 86	    expect(result.uncovered_terms.find((term) => term.id === "interest_bridge")?.reason).toMatch(/monetary_variation/);
 87	    const inventories = by(result, "inventories");
 88	    expect(inventories.explanations.map((explanation) => [explanation.fromSource, explanation.residual, explanation.holds])).toEqual([["nota 5", "0", true], ["release, balanço gerencial", "-40", true], ["release, capital de giro", "37", true]]);
 89	    expect(inventories.state).toBe("explained");
 90	    expect(inventories.explanation_groups).toEqual([["balanço patrimonial, circulante", "nota 5", "release, balanço gerencial", "release, capital de giro"]]);
 91	    expect(inventories.unexplained_sources).toHaveLength(0);
 92	    expect(result.trace.calculations.find((calculation) => calculation.id === "financial.accounting_identity:inventories:explanation:nota 5->balanço patrimonial, circulante")?.anchors.adjustment).toEqual(itr(21, "5, abertura circulante e não circulante"));
 93	    const dividends = by(result, "dividends");
 94	    expect(dividends.state).toBe("not_comparable");
 95	    expect(dividends.spread).toBe("97502");
 96	    // The two carrying amounts share definition, components and date: compared among themselves, they differ by 16.067 and stay open.
 97	    expect(dividends.comparable_subsets).toEqual([{definitionKey: "dividends.carrying_amount", components: ["carrying_amount", "dividends_declared"], asOf, sources: ["balanço (valor presente)", "nota 25 contábil"], spread: "16067", state: "open"}]);
 98	    expect(by(result, "net_debt_release").state).toBe("closes");
 99	    expect(by(result, "net_debt_release_vs_contractual").state).toBe("not_comparable");
100	    expect(by(result, "net_debt_release_vs_contractual").comparability.reasons[0]).toMatch(/different definitions/);
101	    expect(by(result, "leases").state).toBe("single_source");
102	    expect(result.open_divergences.map((entry) => entry.id)).toEqual(["dividends", "net_debt_release_vs_contractual", "dividends:dividends.carrying_amount"]);
103	    expect(result.open_divergences.find((entry) => entry.id === "dividends")?.reason).toMatch(/among themselves, balanço \(valor presente\) and nota 25 contábil \(dividends.carrying_amount\) differ by 16067 and stay open/);
104	    expect(result.open_divergences.find((entry) => entry.id === "dividends:dividends.carrying_amount")?.values.map((value) => value.value)).toEqual(["338565", "322498"]);
