142	  it("refuses duplicates, an explanation naming an unknown source, a tolerance without a registered policy at its current version, and blocks an empty base", () => {
143	    const base = camil();
144	    expect(() => reconcileFinancialStatements({...base, pairedAccounts: [...base.pairedAccounts!, base.pairedAccounts![0]!]})).toThrow(/duplicate account/);
